20	declare_lint_rule! {
21	    /// Enforce that anchors have content and that the content is accessible to screen readers.
22	    ///
23	    /// Accessible means the content is not hidden using the `aria-hidden` attribute.
24	    /// Anchor tags should have text content that describes the link destination for screen reader users.
25	    /// Alternatively, the anchor can have an accessible name via the `aria-label` or `title` attribute.
26	    ///
27	    /// :::note
28	    /// In `.html` files, this rule matches element names case-insensitively (e.g., `<A>`, `<a>`).
29	    ///
30	    /// In component-based frameworks (Vue, Svelte, Astro), only lowercase element names are checked.
31	    /// PascalCase variants like `<A>` are assumed to be custom components and are ignored.
32	    /// :::
33	    ///
34	    /// ## Examples
35	    ///
36	    /// ### Invalid
37	    ///
38	    /// ```html,expect_diagnostic
39	    /// <a></a>
40	    /// ```
41	    ///
42	    /// ```html,expect_diagnostic
43	    /// <a>   </a>
44	    /// ```
45	    ///
46	    /// ```html,expect_diagnostic
47	    /// <a aria-hidden="true">content</a>
48	    /// ```
49	    ///
50	    /// ```html,expect_diagnostic
51	    /// <a><span aria-hidden="true">content</span></a>
52	    /// ```
53	    ///
54	    /// ### Valid
55	    ///
56	    /// ```html
57	    /// <a>content</a>
58	    /// ```
59	    ///
60	    /// ```html
61	    /// <a><span>content</span></a>
62	    /// ```
63	    ///
64	    /// ```html
65	    /// <a><span aria-hidden="true"></span>content</a>
66	    /// ```
67	    ///
68	    /// ```html
69	    /// <a aria-label="Navigate to home"></a>
70	    /// ```
71	    ///
72	    /// ```html
73	    /// <a title="Home page"></a>
74	    /// ```
75	    ///
76	    /// ## Accessibility guidelines
77	    ///
78	    /// - [WCAG 2.4.4](https://www.w3.org/WAI/WCAG21/Understanding/link-purpose-in-context)
79	    /// - [WCAG 4.1.2](https://www.w3.org/WAI/WCAG21/Understanding/name-role-value)
80	    ///
81	    pub UseAnchorContent {
82	        version: "2.4.0",
83	        name: "useAnchorContent",
84	        language: "html",
85	        sources: &[RuleSource::EslintJsxA11y("anchor-has-content").same()],
86	        recommended: true,
87	        severity: Severity::Error,
88	        fix_kind: FixKind::Unsafe,
89	    }
90	}
