11	declare_lint_rule! {
12	    /// Disallow `javascript:` URLs in HTML.
13	    ///
14	    /// Using `javascript:` URLs is considered a form of `eval` and can be a security risk.
15	    /// These URLs can execute arbitrary JavaScript code, which can lead to cross-site scripting (XSS) vulnerabilities.
16	    ///
17	    /// ## Examples
18	    ///
19	    /// ### Invalid
20	    ///
21	    /// ```html,expect_diagnostic
22	    /// <a href="javascript:void(0)">Click me</a>
23	    /// ```
24	    ///
25	    /// ```html,expect_diagnostic
26	    /// <a href="javascript:alert('XSS')">Click me</a>
27	    /// ```
28	    ///
29	    /// ### Valid
30	    ///
31	    /// ```html
32	    /// <a href="https://example.com">Click me</a>
33	    /// <a href="/path/to/page">Click me</a>
34	    /// <a href="#section">Click me</a>
35	    /// <span href="javascript:void(0)">Not a real href</span>
36	    /// ```
37	    ///
38	    pub NoScriptUrl {
39	        version: "2.3.9",
40	        name: "noScriptUrl",
41	        language: "html",
42	        // Show equivalents from related ecosystems
43	        sources: &[
44	            RuleSource::Eslint("no-script-url").same(),
45	            RuleSource::EslintReact("jsx-no-script-url").same(),
46	            RuleSource::EslintQwik("jsx-no-script-url").same(),
47	            RuleSource::EslintSolid("jsx-no-script-url").same(),
48	            RuleSource::EslintReactXyz("dom-no-script-url").same(),
49	        ],
50	        recommended: true,
51	        severity: Severity::Error,
52	    }
53	}
54	
55	impl Rule for NoScriptUrl {
56	    type Query = Ast<HtmlOpeningElement>;
57	    type State = TextRange;
58	    type Signals = Option<Self::State>;
59	    type Options = NoScriptUrlOptions;
60	
61	    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
62	        let element = ctx.query();
63	
64	        // Only check <a> elements for HTML (unlike JSX where components/custom elements exist)
65	        let name = element.name().ok()?;
66	        let tag = name.token_text_trimmed()?;
67	        if !tag.eq_ignore_ascii_case("a") {
68	            return None;
69	        }
70	
71	        let attrs = element.attributes();
72	        let attr = attrs.find_by_name("href")?;
73	        let initializer = attr.initializer()?;
74	        let value = initializer.value().ok()?;
75	
76	        if let AnyHtmlAttributeInitializer::HtmlString(html_string) = value
77	            && let Ok(token) = html_string.value_token()
78	        {
79	            let inner = inner_string_text(&token);
80	            if inner.trim().to_lowercase_cow().starts_with("javascript:") {
81	                return Some(initializer.range());
82	            }
83	        }
84	
85	        None
86	    }
87	
88	    fn diagnostic(_ctx: &RuleContext<Self>, range: &Self::State) -> Option<RuleDiagnostic> {
89	        Some(
90	            RuleDiagnostic::new(
91	                rule_category!(),
92	                *range,
93	                markup! {
94	                    "Avoid using "<Emphasis>"javascript:"</Emphasis>" URLs, as they can be a security risk."
95	                },
96	            )
97	            .note(markup! {
98	                "Using "<Emphasis>"javascript:"</Emphasis>" URLs can lead to security vulnerabilities such as cross-site scripting (XSS)."
99	            })
100	            .note(markup! {
101	                "Consider using regular URLs, or if you need to handle click events, use event handlers instead."
102	            }),
103	        )
104	    }
105	}
