9	declare_lint_rule! {
10	    /// Enforces the usage and validity of the attribute `type` for the element `button`
11	    ///
12	    /// ## Examples
13	    ///
14	    /// ### Invalid
15	    ///
16	    /// ```html,expect_diagnostic
17	    /// <button>Do something</button>
18	    /// ```
19	    ///
20	    /// ```html,expect_diagnostic
21	    /// <button type="incorrectType">Do something</button>
22	    /// ```
23	    ///
24	    /// ### Valid
25	    ///
26	    /// ```html
27	    /// <button type="button">Do something</button>
28	    /// ```
29	    ///
30	    pub UseButtonType {
31	        version: "2.4.0",
32	        name: "useButtonType",
33	        language: "html",
34	        sources: &[RuleSource::EslintReact("button-has-type").same(), RuleSource::HtmlEslint("require-button-type").same()],
35	        recommended: true,
